const ignore = () => [{json: {eligible: false} }];
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const id = (value, zero = false) => Number.isSafeInteger(value) && value >= (zero ? 0 : 1) && value <= 999999999999999 ? String(value) : null;
const body = $input.first().json.body;
if (!object(body) || Object.keys(body).some(k => !['update_id', 'message'].includes(k)) ||
    !object(body.message) || !id(body.update_id, true)) return ignore();
const m = body.message;
if (!object(m.from) || !object(m.chat) || !id(m.from.id) || !id(m.chat.id) ||
    !id(m.message_id) || m.chat.type !== 'private' || m.from.is_bot !== false ||
    !Number.isSafeInteger(m.date) || m.date < 1 || m.date > 253402300799) return ignore();
if (['photo','audio','document','video','video_note','animation','sticker','contact','location','venue','poll','dice','game','paid_media','caption'].some(k => m[k] !== undefined)) return ignore();
let kind, message;
if (object(m.voice) && m.text === undefined) {
  const v = m.voice;
  if (typeof v.file_id !== 'string' || !v.file_id.trim() || v.file_id.length > 1024 ||
      typeof v.file_unique_id !== 'string' || !v.file_unique_id.trim() || v.file_unique_id.length > 256 ||
      !Number.isInteger(v.duration) || v.duration < 0 || v.duration > 2147483647) return ignore();
  message = {fileId: v.file_id, fileUniqueId: v.file_unique_id, durationSeconds: v.duration};
  if (v.mime_type !== undefined) {
    if (typeof v.mime_type !== 'string' || v.mime_type.length > 200) return ignore();
    message.mimeType = v.mime_type;
  }
  if (v.file_size !== undefined) {
    if (!id(v.file_size, true)) return ignore();
    message.sizeBytes = v.file_size;
  }
  kind = 'voice';
} else if (typeof m.text === 'string' && m.voice === undefined) {
  if (!m.text.trim() || m.text.length > 16000 || Array.from(m.text.trim()).length > 8000) return ignore();
  message = {text: m.text};
  if (m.reply_to_message !== undefined) {
    if (!object(m.reply_to_message) || !id(m.reply_to_message.message_id)) return ignore();
    message.replyToMessageId = m.reply_to_message.message_id;
  }
  kind = 'text';
} else return ignore();
message.sentAt = new Date(m.date * 1000).toISOString();
const serialized = JSON.stringify(message);
let bytes = 0;
for (const ch of serialized) { const cp = ch.codePointAt(0); bytes += cp <= 127 ? 1 : cp <= 2047 ? 2 : cp <= 65535 ? 3 : 4; }
if (bytes > 32768 || serialized.includes('\\u0000')) return ignore();
return [{json: {
  eligible: true, updateId: id(body.update_id, true), operatorUserId: id(m.from.id),
  chatId: id(m.chat.id), messageId: id(m.message_id), chatType: 'private',
  senderIsBot: false, kind, message, messageBytes: bytes
} }];

const config = $input.first().json;
const envelope = $('Sanitize Telegram Update').first().json;
const positive = v => typeof v === 'string' && /^[1-9][0-9]{0,14}$/.test(v) && Number.isSafeInteger(Number(v));
if (!config.configVersion || !positive(config.botId) || !positive(config.operatorUserId) ||
    !positive(config.operatorChatId) || config.ingressPolicy?.requirePrivateChat !== true ||
    config.ingressPolicy?.requireHumanSender !== true || config.ingressPolicy?.expectedUpdateType !== 'message' ||
    !Number.isInteger(config.retryPolicy?.stageMaxAttempts) || config.retryPolicy.stageMaxAttempts < 1 ||
    config.retryPolicy.stageMaxAttempts > 20 || config.retryPolicy.blindWriteRetries !== false) {
  throw new Error('Ticket intake configuration is unavailable or invalid');
}
if (envelope.eligible !== true || envelope.operatorUserId !== config.operatorUserId ||
    envelope.chatId !== config.operatorChatId || envelope.chatType !== 'private' ||
    envelope.senderIsBot !== false || !config.ingressPolicy.supportedKinds?.includes(envelope.kind)) {
  return [{json: {persist: false} }];
}
const policy = {
  configVersion: config.configVersion,
  ingressPolicy: config.ingressPolicy,
  retryPolicy: config.retryPolicy,
  priorityPolicy: config.priorityPolicy,
  phase: config.phase
};
return [{json: {persist: true, queryParameters: [
  config.botId, envelope.updateId, config.operatorUserId, config.operatorChatId,
  envelope.messageId, envelope.kind, JSON.stringify(envelope.message), JSON.stringify(policy)
]} }];

const r = $input.first().json.receipt;
const expected = $('Authorize Operator and Prepare Parameters').first().json.queryParameters;
if (!r || r.found !== true || !r.messageId ||
    !['accepted', 'duplicate_message', 'duplicate_voice'].includes(r.outcome) ||
    String(r.updateId) !== expected[1] || String(r.telegramMessageId) !== expected[4]) {
  throw new Error('Persistence receipt is missing or inconsistent');
}
return [{json: {ok: true} }];
